func (r *GormSessionRepository) List(ctx context.Context, parent string, in repox.ListInput) ([]*bookingpbv1.Session, string, error) {
	parentIDs, err := repox.SplitName(parent, "venues", "events")
	if err != nil {
		return nil, "", err
	}
	// AIP-159: "-" for the parent reads across every parent; narrow with a
	// Where on the parent field instead.
	if parentIDs[len(parentIDs)-1] == "-" {
		return r.list(ctx, r.DB, in)
	}
	// The parent is nested, so its row is found by name.
	op, arg := repox.NameMatch(parent)
	scope := r.DB.Where(`"event_id" IN (SELECT "id" FROM "booking"."events" WHERE "name" `+op+")", arg)
	return r.list(ctx, scope, in)
}

func (r *GormSessionRepository) list(ctx context.Context, scope *gorm.DB, in repox.ListInput) ([]*bookingpbv1.Session, string, error) {
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	eng := filterx.Gorm[booking.Session](booking.SessionFilterSpec)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	if err := repox.CheckReadMask((*bookingpbv1.Session)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	rows, next, err := eng.List(ctx, r.reads(scope, in), filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*bookingpbv1.Session, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i])
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

